with metrics as (select *, cume_dist() over (partition by device_code order by humidity desc nulls last) as humidity_cume_dist, sum(status_bits) over (partition by device_code order by status_bits, id rows between unbounded preceding and current row) as running_status_bits, round(pressure / sum(pressure) over (partition by device_code), 4) as pressure_share from device_readings) select date_trunc('hour', reading_ts) as hour_window, device_code, size(collect_set(device_code)) as num_device_codes, percentile_approx(pressure, array(0.25, 0.5, 0.75)) as pressure_quartiles, approx_percentile(running_status_bits, 0.9) as running_status_bits_p90, rank() over (partition by date_trunc('hour', reading_ts) order by size(collect_set(device_code)) desc) as num_device_codes_rank from metrics group by 1, 2 order by num_device_codes nulls first
